#include <iostream>
#include <memory>
#include <numbers>
#include <print>
#include <sstream>
#include <string>
#include <vector>

struct Shape {
    virtual ~Shape() = default;
    virtual std::string name() const = 0;
    virtual double area() const = 0;
};

struct Circle final : Shape {
    double r;
    explicit Circle(double r) : r(r) {}
    std::string name() const override {
        return "круг";
    }
    double area() const override {
        return std::numbers::pi * r * r;
    }
};

struct Rect final : Shape {
    double w;
    double h;
    Rect(double w, double h) : w(w), h(h) {}
    std::string name() const override {
        return "прямоугольник";
    }
    double area() const override {
        return w * h;
    }
};

struct Square final : Shape {
    double a;
    explicit Square(double a) : a(a) {}
    std::string name() const override {
        return "квадрат";
    }
    double area() const override {
        return a * a;
    }
};

std::unique_ptr<Shape> make_shape(const std::string &line) {
    std::istringstream in(line);
    std::string kind;
    in >> kind;
    if (kind == "circle") {
        double r;
        in >> r;
        return std::make_unique<Circle>(r);
    }
    if (kind == "rect") {
        double w, h;
        in >> w >> h;
        return std::make_unique<Rect>(w, h);
    }
    if (kind == "square") {
        double a;
        in >> a;
        return std::make_unique<Square>(a);
    }
    return nullptr;
}

int main() {
    std::vector<std::unique_ptr<Shape>> shapes;
    std::string line;
    int number = 0;
    while (std::getline(std::cin, line)) {
        ++number;
        if (auto shape = make_shape(line)) {
            shapes.push_back(std::move(shape));
        } else {
            std::println("строка {}: неизвестная фигура", number);
        }
    }
    double total = 0;
    for (std::size_t i = 0; i < shapes.size(); ++i) {
        std::println("{}. {} {:.2f}", i + 1, shapes[i]->name(), shapes[i]->area());
        total += shapes[i]->area();
    }
    std::println("итого: {:.2f}", total);
    return 0;
}

