int main() {
    int n;
    std::cin >> n;
    auto counts = std::make_unique<int[]>(n);
    int outside = 0;
    long long x;
    while (std::cin >> x) {
        if (0 <= x && x < n) {
            ++counts[x];
        } else {
            ++outside;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (counts[i] > 0) {
            std::println("{}: {} {}", i, counts[i], std::string(counts[i], '#'));
        } else {
            std::println("{}: 0", i);
        }
    }
    std::println("вне диапазона: {}", outside);
    return 0;
}

