int main() {
    int n, k;
    std::cin >> n >> k;
    auto buffer = std::make_unique<int>(n);
    int *data = buffer.get();
    for (int i = 0; i < n; ++i) {
        std::cin >> data[i];
    }
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += data[i];
        if (i >= k) {
            sum -= data[i - k];
        }
        if (i >= k - 1) {
            std::print("{}{}", i >= k ? " " : "", sum);
        }
    }
    std::println();
    return 0;
}

