#include <algorithm>
#include <iostream>
#include <memory>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Pool;

class Connection {
public:
    class Key {
        friend class Pool;
        Key() = default;
    };

    Connection(Key, std::string host) : host_(std::move(host)) {}
    Connection(const Connection &) = delete;
    Connection &operator=(const Connection &) = delete;
    ~Connection() {
        std::println("закрыто {}", host_);
    }

    const std::string &host() const {
        return host_;
    }

private:
    std::string host_;
};

class Pool {
public:
    explicit Pool(std::size_t limit) : limit_(limit) {}
    ~Pool() {
        for (auto &c : connections_) {
            c.reset();
        }
    }

    void open(const std::string &host) {
        if (connections_.size() == limit_) {
            std::println("лимит");
        } else if (std::ranges::any_of(connections_, [&](const auto &c) { return c->host() == host; })) {
            std::println("уже открыто {}", host);
        } else {
            connections_.push_back(std::make_unique<Connection>(Connection::Key{}, host));
            std::println("открыто {} ({}/{})", host, connections_.size(), limit_);
        }
    }

    void close(const std::string &host) {
        if (std::erase_if(connections_, [&](const auto &c) { return c->host() == host; }) == 0) {
            std::println("нет {}", host);
        }
    }

    void list() const {
        if (connections_.empty()) {
            std::println("пусто");
            return;
        }
        std::string line;
        for (const auto &c : connections_) {
            line += (line.empty() ? "" : " ") + c->host();
        }
        std::println("{}", line);
    }

private:
    std::size_t limit_;
    std::vector<std::unique_ptr<Connection>> connections_;
};

int main() {
    std::size_t limit;
    std::cin >> limit;
    Pool pool(limit);
    std::string command;
    while (std::cin >> command) {
        if (command == "list") {
            pool.list();
            continue;
        }
        std::string host;
        std::cin >> host;
        if (command == "open") {
            pool.open(host);
        } else {
            pool.close(host);
        }
    }
    std::println("конец");
    return 0;
}

